#!/usr/bin/env python3
"""Filter and aggregate RFC-4180-style CSV files."""

from __future__ import annotations

import argparse
import csv
import json
import sys
from collections.abc import Sequence
from decimal import Decimal, InvalidOperation
from pathlib import Path


class CsvInsightsError(Exception):
    """An input or validation error that is safe to show to the user."""


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Filter CSV rows and optionally calculate grouped sums and averages."
    )
    parser.add_argument("input", metavar="INPUT.csv", help="CSV file to analyze")
    parser.add_argument(
        "--where",
        action="append",
        default=[],
        metavar="COLUMN=VALUE",
        help="keep rows whose column exactly equals value (repeatable)",
    )
    parser.add_argument("--group-by", metavar="COLUMN", help="column used to group rows")
    parser.add_argument(
        "--sum",
        dest="sum_columns",
        action="append",
        default=[],
        metavar="COLUMN",
        help="numeric column to sum (repeatable)",
    )
    parser.add_argument(
        "--avg",
        dest="avg_columns",
        action="append",
        default=[],
        metavar="COLUMN",
        help="numeric column to average (repeatable)",
    )
    parser.add_argument(
        "--output", choices=("json", "csv"), default="json", help="output format (default: json)"
    )
    return parser


def parse_filters(raw_filters: Sequence[str]) -> list[tuple[str, str]]:
    filters: list[tuple[str, str]] = []
    for raw_filter in raw_filters:
        if "=" not in raw_filter:
            raise CsvInsightsError(
                f"malformed filter {raw_filter!r}: expected COLUMN=VALUE"
            )
        column, value = raw_filter.split("=", 1)
        if not column:
            raise CsvInsightsError(
                f"malformed filter {raw_filter!r}: column name cannot be empty"
            )
        filters.append((column, value))
    return filters


def validate_arguments(args: argparse.Namespace) -> list[tuple[str, str]]:
    has_aggregation = bool(args.sum_columns or args.avg_columns)
    if has_aggregation and not args.group_by:
        raise CsvInsightsError("--sum and --avg require --group-by")
    if args.group_by and not has_aggregation:
        raise CsvInsightsError("--group-by requires at least one --sum or --avg")

    for option, columns in (("--sum", args.sum_columns), ("--avg", args.avg_columns)):
        duplicates = sorted({column for column in columns if columns.count(column) > 1})
        if duplicates:
            raise CsvInsightsError(
                f"duplicate {option} column(s): {', '.join(repr(value) for value in duplicates)}"
            )
    return parse_filters(args.where)


def read_csv(path: str) -> tuple[list[str], list[tuple[int, list[str]]]]:
    try:
        with Path(path).open("r", encoding="utf-8", newline="") as input_file:
            reader = csv.reader(input_file, strict=True)
            try:
                header = next(reader)
            except StopIteration as error:
                raise CsvInsightsError("input CSV is empty; a header row is required") from error

            if not header:
                raise CsvInsightsError("header row is empty")
            empty_positions = [str(index + 1) for index, name in enumerate(header) if not name.strip()]
            if empty_positions:
                raise CsvInsightsError(
                    f"header names must be non-empty (field(s) {', '.join(empty_positions)})"
                )
            duplicate_headers = sorted({name for name in header if header.count(name) > 1})
            if duplicate_headers:
                raise CsvInsightsError(
                    "header names must be unique; duplicate(s): "
                    + ", ".join(repr(name) for name in duplicate_headers)
                )

            rows: list[tuple[int, list[str]]] = []
            for record_number, row in enumerate(reader, start=2):
                if len(row) != len(header):
                    raise CsvInsightsError(
                        f"row {record_number} has {len(row)} fields; expected {len(header)}"
                    )
                rows.append((record_number, row))
            return header, rows
    except CsvInsightsError:
        raise
    except csv.Error as error:
        raise CsvInsightsError(f"malformed CSV: {error}") from error
    except UnicodeError as error:
        raise CsvInsightsError(f"input is not valid UTF-8: {error}") from error
    except OSError as error:
        raise CsvInsightsError(f"cannot read {path!r}: {error}") from error


def require_columns(header: Sequence[str], requested: Sequence[tuple[str, str]]) -> None:
    known = set(header)
    for column, option in requested:
        if column not in known:
            raise CsvInsightsError(f"unknown column {column!r} in {option}")


def decimal_value(value: str, row_number: int, column: str) -> Decimal:
    if not value:
        raise CsvInsightsError(f"invalid numeric value at row {row_number}, column {column!r}: blank")
    try:
        number = Decimal(value)
    except InvalidOperation as error:
        raise CsvInsightsError(
            f"invalid numeric value at row {row_number}, column {column!r}: {value!r}"
        ) from error
    if not number.is_finite():
        raise CsvInsightsError(
            f"invalid numeric value at row {row_number}, column {column!r}: {value!r}"
        )
    return number


def format_decimal(number: Decimal) -> str:
    if number == 0:
        return "0"
    text = format(number, "f")
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    return text


def filtered_rows(
    header: Sequence[str],
    rows: Sequence[tuple[int, list[str]]],
    filters: Sequence[tuple[str, str]],
) -> list[tuple[int, list[str]]]:
    indexes = [(header.index(column), value) for column, value in filters]
    return [
        (row_number, row)
        for row_number, row in rows
        if all(row[index] == value for index, value in indexes)
    ]


def aggregate(
    header: Sequence[str],
    rows: Sequence[tuple[int, list[str]]],
    group_by: str,
    sum_columns: Sequence[str],
    avg_columns: Sequence[str],
) -> tuple[list[str], list[list[str]]]:
    group_index = header.index(group_by)
    numeric_columns = list(dict.fromkeys([*sum_columns, *avg_columns]))
    numeric_indexes = {column: header.index(column) for column in numeric_columns}
    groups: dict[str, dict[str, tuple[Decimal, int]]] = {}

    for row_number, row in rows:
        group = row[group_index]
        parsed = {
            column: decimal_value(row[index], row_number, column)
            for column, index in numeric_indexes.items()
        }
        values = groups.setdefault(group, {})
        for column, number in parsed.items():
            total, count = values.get(column, (Decimal(0), 0))
            values[column] = (total + number, count + 1)

    output_header = [
        group_by,
        *(f"sum_{column}" for column in sum_columns),
        *(f"avg_{column}" for column in avg_columns),
    ]
    output_rows: list[list[str]] = []
    for group in sorted(groups):
        values = groups[group]
        output_rows.append(
            [
                group,
                *(format_decimal(values[column][0]) for column in sum_columns),
                *(
                    format_decimal(values[column][0] / values[column][1])
                    for column in avg_columns
                ),
            ]
        )
    return output_header, output_rows


def emit_json(header: Sequence[str], rows: Sequence[Sequence[str]]) -> None:
    result = [dict(zip(header, row, strict=True)) for row in rows]
    json.dump(result, sys.stdout, ensure_ascii=False, indent=2)
    sys.stdout.write("\n")


def emit_csv(header: Sequence[str], rows: Sequence[Sequence[str]]) -> None:
    writer = csv.writer(sys.stdout, lineterminator="\r\n")
    writer.writerow(header)
    writer.writerows(rows)


def run(args: argparse.Namespace) -> None:
    filters = validate_arguments(args)
    header, numbered_rows = read_csv(args.input)
    referenced_columns = [
        *((column, "--where") for column, _ in filters),
        *((column, "--sum") for column in args.sum_columns),
        *((column, "--avg") for column in args.avg_columns),
    ]
    if args.group_by:
        referenced_columns.append((args.group_by, "--group-by"))
    require_columns(
        header,
        referenced_columns,
    )
    selected = filtered_rows(header, numbered_rows, filters)

    if args.group_by:
        output_header, output_rows = aggregate(
            header, selected, args.group_by, args.sum_columns, args.avg_columns
        )
    else:
        output_header = list(header)
        output_rows = [row for _, row in selected]

    if args.output == "json":
        emit_json(output_header, output_rows)
    else:
        emit_csv(output_header, output_rows)


def main(argv: Sequence[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
# CSV Insights

A dependency-free Python 3.11+ command-line tool for filtering CSV files and
computing grouped sums and averages with exact decimal arithmetic.

```bash
python3 main.py INPUT.csv [--where COLUMN=VALUE ...] [--group-by COLUMN] \
  [--sum COLUMN ...] [--avg COLUMN ...] [--output json|csv]
```

Filters use exact string comparison and combine with AND. Without aggregation,
matching rows are emitted in their original order. `--sum` and `--avg` are
repeatable and require `--group-by`; grouped output is sorted by group value.
The default output is JSON.

Examples:

```bash
python3 main.py sales.csv --where region=East
python3 main.py sales.csv --group-by region --sum revenue --avg units --output csv
```

Input must be UTF-8 CSV with one non-empty, unique name per header field and a
consistent field count. Quoted commas and embedded newlines are supported.
Invalid or blank cells in aggregated numeric columns are reported with their
logical CSV row and column.
[
  {
    "group": "a",
    "sum_value": "2.5",
    "avg_value": "2.5"
  },
  {
    "group": "b",
    "sum_value": "2",
    "avg_value": "1"
  }
]

